def preview(ids):
    reads = 0

    def read(group):
        nonlocal reads
        assert 1 <= len(group) <= 3
        reads += 1
        if reads > 5:
            raise ValueError('read allowance exceeded')
        return [item * 10 for item in group]

    prices = []
    for start in range(0, len(ids), 1):
        prices.extend(read(ids[start:start + 1]))
    return prices, reads

for count in (1, 5, 6, 12):
    ids = list(range(1, count + 1))
    try:
        prices, reads = preview(ids)
        assert prices == [item * 10 for item in ids]
        print(count, reads)
    except ValueError as error:
        print(count, error)

def preview(ids):
